    if (typeof img === 'string') { var m = /^https:\/\/static\.wixstatic\.com\/media\/([0-9a-f]+_[0-9a-f]{32}~mv2\.(?:jpe?g|png|webp|avif))(?:[\/?#].*)?$/i.exec(img); return m ? m[1] : ''; }
